 * @param ucTablePrefix The Unity Catalog location fields
 */
export function ucTablePrefixLocationString(ucTablePrefix: {
  catalogName: string;
  schemaName: string;
  tablePrefix: string;
}): string {
  return `${ucTablePrefix.catalogName}.${ucTablePrefix.schemaName}.${ucTablePrefix.tablePrefix}`;
}

/**
 * Return the dot-separated 'catalog.schema.prefix' string for a UC table-prefix
 * TraceLocation, or null if the location is not a UC location or has no ucTablePrefix.
 * @param loc The trace location
 */
export function getUcLocationString(loc: TraceLocation): string | null {
  if (!isUcTraceLocation(loc) || !loc.ucTablePrefix) {
    return null;
  }
  const { catalogName, schemaName, tablePrefix } = loc.ucTablePrefix;
  if (tablePrefix == null) {
    return null;
  }
  return ucTablePrefixLocationString({ catalogName, schemaName, tablePrefix });
}

