 *
 * If `ucTablePrefix.otelSpansTableName` is explicitly set, that value is returned.
 * Otherwise the default '<catalog>.<schema>.<prefix>_otel_spans' is returned. Returns
 * null if the location has no tablePrefix set.
 * @param loc The trace location
 */
export function getOtelSpansTableName(loc: TraceLocation): string | null {
  if (!isUcTraceLocation(loc) || !loc.ucTablePrefix) {
    return null;
  }
  const { catalogName, schemaName, tablePrefix, otelSpansTableName } = loc.ucTablePrefix;
  if (otelSpansTableName) {
    return otelSpansTableName;
  }
  if (tablePrefix == null) {
    return null;
  }
  return `${catalogName}.${schemaName}.${tablePrefix}_otel_spans`;
