/**
 * Prefix for v4 (Unity Catalog) trace IDs: 'trace:/<location>/<otelTraceId>'.
 */
export const TRACE_ID_V4_PREFIX = 'trace:/';

/**
 * Parse a v4 trace ID string of the form 'trace:/<location>/<otelTraceId>'.
 *
 * Returns a tuple `[locationString, otelTraceId]`. For non-v4 trace IDs (e.g.
 * 'tr-<id>'), returns `[null, rawTraceId]`. For strings that begin with the v4
 * prefix but are structurally malformed (missing the trace ID segment or with an
 * empty location), an error whose message matches /Invalid trace ID format/ is thrown.
 *
 * @param traceId The trace ID to parse
 */
export function parseTraceIdV4(traceId: string): [string | null, string] {
  if (traceId.startsWith(TRACE_ID_V4_PREFIX)) {
    const parts = traceId.slice(TRACE_ID_V4_PREFIX.length).split('/');
    if (parts.length === 2 && parts[0] && parts[1]) {
      return [parts[0], parts[1]];
    }
    throw new Error(
      `Invalid trace ID format: ${traceId}. ` +
        `Expected format: ${TRACE_ID_V4_PREFIX}<location>/<trace_id>`,
    );
  }
  return [null, traceId];
}

/**
 * Construct a v4 trace ID for the given location and OpenTelemetry trace ID.
 * @param location The location string (e.g. 'catalog.schema.prefix')
 * @param otelTraceId The OpenTelemetry trace ID
 */
export function constructTraceIdV4(location: string, otelTraceId: string): string {
  return `${TRACE_ID_V4_PREFIX}${location}/${otelTraceId}`;
}

/**
 * Generate a v3 trace ID ('tr-<otelTraceId>') for the given OpenTelemetry trace ID.
 * @param otelTraceId The OpenTelemetry trace ID
 */
export function generateTraceIdV3(otelTraceId: string): string {
  return TRACE_ID_PREFIX + otelTraceId;
}
