      const tableName = getOtelSpansTableName(traceInfo.traceLocation);
      if (!tableName) {
        console.warn(`No OTLP spans table name resolved for trace ${trace.info.traceId}. Skipping.`);
        return;
      }

      const otelSpans = trace.data.spans.map((span) => span._span);
      await this._client.exportOtlpSpansToUc(otelSpans, tableName);
    } finally {
      delete this._pendingExports[trace.info.traceId];
    }
  }

  /**
   * Force flush all pending trace exports.
   */
  async forceFlush(): Promise<void> {
    await Promise.all(Object.values(this._pendingExports));
    this._pendingExports = {};
  }

  /**
   * Shutdown the exporter. Waits for all pending exports to complete.
   */
  async shutdown(): Promise<void> {
    await this.forceFlush();
  }
}

